use strict;
use warnings;
my %runs;
for my $file (@ARGV) {
    my (%groups, %metadata, %seen);
    open my $fh, '<', $file or die "$file: $!";
    while (<$fh>) {
        if (/Block\{ hash: (\S+) parent: .* proposer: (\d+), view: (\d+)/) {
            $metadata{$1} = [$2, $3];
        }
        if (/\s(hs\d+)\s+votingmachine\/votingmachine\.go:\d+\s+CollectVote\(from (\d+)\): (\S+)/) {
            my ($receiver, $sender, $block) = ($1, $2, $3);
            my $key = "$receiver|$block";
            next if $seen{"$key|$sender"}++;
            push @{$groups{$key}}, $sender;
        }
    }
    close $fh;
    my (%sizes, %rank, %first, %last, %per_receiver, %meta_views, %orders);
    my $allgroups = 0;
    for my $key (keys %groups) {
        my ($receiver, $block) = split /\|/, $key, 2;
        my @senders = @{$groups{$key}};
        $sizes{scalar @senders}++;
        next unless @senders == 4;
        $allgroups++;
        my ($proposer, $view) = @{$metadata{$block} // ["?", "?"]};
        $meta_views{$view}++;
        $orders{join('-', @senders)}++;
        $first{$senders[0]}++;
        $last{$senders[-1]}++;
        $per_receiver{$receiver}{count}++;
        $per_receiver{$receiver}{first}{$senders[0]}++;
        $per_receiver{$receiver}{last}{$senders[-1]}++;
        for my $i (0..$#senders) { $rank{$senders[$i]}[$i]++; }
    }
    my $out = "\n$file\n";
    $out .= "unique receiver/block groups=" . scalar(keys %groups) . "; sizes=" . join(', ', map { "$_:" . ($sizes{$_}//0) } sort {$a<=>$b} keys %sizes) . "\n";
    $out .= "complete four-sender observations=$allgroups; distinct block hashes=" . scalar(keys %metadata) . "\n";
    for my $sender (1..4) {
        my @ranks = map { $rank{$sender}[$_] // 0 } 0..3;
        my $total = 0; $total += $_ for @ranks;
        my $mean = $total ? sprintf('%.3f', (1*$ranks[0] + 2*$ranks[1] + 3*$ranks[2] + 4*$ranks[3])/$total) : 'n/a';
        $out .= "sender $sender: ranks=" . join(',',@ranks) . "; first=" . ($first{$sender}//0) . "; last=" . ($last{$sender}//0) . "; mean-rank=$mean\n";
    }
    for my $receiver (sort keys %per_receiver) {
        my $data = $per_receiver{$receiver};
        my @f = map { $data->{first}{$_}//0 } 1..4;
        my @l = map { $data->{last}{$_}//0 } 1..4;
        $out .= "$receiver ($data->{count} complete): first=" . join(',',@f) . "; last=" . join(',',@l) . " [IDs 1..4]\n";
    }
    my @common = sort { $orders{$b}<=>$orders{$a} } keys %orders;
    $out .= "most frequent full orders: " . join('; ', map { "$_=$orders{$_}" } @common[0..($#common<4?$#common:4)]) . "\n" if @common;
    print $out;
}
PERL

