use strict;
use warnings;
my (%total_first, %total_last, $total_groups);
for my $file (@ARGV) {
    my (%groups, %seen);
    open my $fh, '<', $file or die "$file: $!";
    while (<$fh>) {
        next unless /\s(hs\d+)\s+votingmachine\/votingmachine\.go:\d+\s+CollectVote\(from (\d+)\): (\S+)/;
        my ($receiver, $sender, $block) = ($1, $2, $3);
        my $key = "$receiver|$block";
        next if $seen{"$key|$sender"}++;
        push @{$groups{$key}}, $sender;
    }
    close $fh;
    my (%first, %last, $n);
    for my $senders (values %groups) {
        next unless @$senders == 4;
        $n++;
        $first{$senders->[0]}++;
        $last{$senders->[-1]}++;
    }
    $total_groups += $n;
    $total_first{$_} += $first{$_} // 0 for 1..4;
    $total_last{$_} += $last{$_} // 0 for 1..4;
    print "$file complete_groups=$n first=[", join(',', map {$first{$_}//0} 1..4), "] last=[", join(',', map {$last{$_}//0} 1..4), "]\n";
}
print "TOTAL groups=$total_groups\n";
for my $id (1..4) {
    printf "replica %d first=%d (%.2f%%) latest=%d (%.2f%%)\n", $id, $total_first{$id}, 100*$total_first{$id}/$total_groups, $total_last{$id}, 100*$total_last{$id}/$total_groups;
}
PERL

